import sys

def find_string(a_00, a_01, a_10, a_11):
    if a_00 + a_01 != a_10 + a_11:
        return "Impossible"

    result = []
    if a_00 > 0:
        result.append('0')
    if a_01 > 0:
        result.append('1')
    if a_10 > 0:
        result.append('0')
    if a_11 > 0:
        result.append('1')

    # Fill the remaining characters
    while len(result) < 1000000:
        if a_00 > 0:
            result.append('0')
            a_00 -= 1
        elif a_01 > 0:
            result.append('1')
            a_01 -= 1
        elif a_10 > 0:
            result.append('0')
            a_10 -= 1
        elif a_11 > 0:
            result.append('1')
            a_11 -= 1

    return ''.join(result[:min(len(result), 1000000)])

