    if a_00 + a_01 != a_10 + a_11:
        return "Impossible"

    if a_00 == 0 and a_01 == 0 and a_10 == 0 and a_11 == 0:
        return ""

    if a_00 > 0:
        result = "0" * a_00
    elif a_10 > 0:
        result = "1" * a_10
    else:
        return "Impossible"

    if a_01 > 0:
        result += "1" * a_01 + "0" * (a_01 - 1)
    elif a_11 > 0:
        result += "0" * a_11 + "1" * (a_11 - 1)
    else:
        return "Impossible"

    return result

