import sys

def find_string(a00, a01, a10, a11):
    if a00 > 0 and (a01 == 0 or a10 == 0):
        return "Impossible"
    if a01 > 0 and (a00 == 0 or a11 == 0):
        return "Impossible"
    if a10 > 0 and (a00 == 0 or a11 == 0):
        return "Impossible"
    if a11 > 0 and (a01 == 0 or a10 == 0):
        return "Impossible"

    if a00 + a01 + a10 + a11 <= 2:
        return "Impossible"

    result = []
    for _ in range(a00):
        result.append('0')
        result.append('0')
    for _ in range(a01):
        result.append('0')
        result.append('1')
    for _ in range(a10):
        result.append('1')
        result.append('0')
    for _ in range(a11):
        result.append('1')
        result.append('1')

    return ''.join(result)

